<?php
declare(strict_types=1);

require dirname(__DIR__) . '/app/bootstrap.php';

use Aetherfall\Support\Database;

$pdo=Database::connection();$classes=(int)$pdo->query('SELECT COUNT(*) FROM classes')->fetchColumn();$resources=(int)$pdo->query('SELECT COUNT(*) FROM class_resources')->fetchColumn();$resourceAbilities=0;$valid=0;$invalid=[];$definitions=[];foreach($pdo->query('SELECT c.id class_id,c.name class_name,cr.resource_id,cr.name resource_name,cr.maximum_formula,cr.start_value FROM classes c LEFT JOIN class_resources cr ON cr.class_id=c.id ORDER BY c.id,cr.resource_id') as $row){$definitions[]=$row;}
$abilities=$pdo->query('SELECT id,class_id,costs,class_resource,source_file FROM abilities')->fetchAll();
foreach($abilities as $ability){$text=trim((string)$ability['costs'].' '.(string)$ability['class_resource']);if($text==='')continue;$resourceAbilities++;$defs=$pdo->prepare('SELECT name,resource_id FROM class_resources WHERE class_id=?');$defs->execute([$ability['class_id']]);$known=$defs->fetchAll();$found=false;foreach($known as $definition){$needles=[(string)$definition['name'],(string)$definition['resource_id']];foreach($needles as $needle){$words=preg_split('/[^\p{L}\p{N}]+/u',mb_strtolower($needle))?:[];$hay=mb_strtolower($text);$matches=$words!==[];foreach($words as $word){if($word===''||mb_strlen($word)<4)continue;$matches=$matches&&mb_strpos($hay,mb_substr($word,0,5))!==false;}if($matches){$found=true;break;}}if($found)break;}if(!$found&&count($known)===1&&preg_match('/primärressource|grundressource|klassenressource/iu',$text))$found=true;if($found)$valid++;else$invalid[]=['ability'=>$ability['id'],'class'=>$ability['class_id'],'reference'=>$text,'source'=>$ability['source_file']];}
$characterInvalid=(int)$pdo->query('SELECT COUNT(*) FROM character_class_resources ccr JOIN character_classes cc ON cc.id=ccr.character_class_id LEFT JOIN class_resources cr ON cr.class_id=cc.class_id AND cr.resource_id=ccr.class_resource_id WHERE cr.resource_id IS NULL')->fetchColumn();
$combatInvalid=(int)$pdo->query('SELECT COUNT(*) FROM combat_participant_resources cpr JOIN combat_participants cp ON cp.id=cpr.combat_participant_id LEFT JOIN character_classes cc ON cc.id=cpr.character_class_id AND cc.character_id=cp.reference_id LEFT JOIN class_resources cr ON cr.class_id=cc.class_id AND cr.resource_id=cpr.class_resource_id WHERE cc.id IS NULL OR cr.resource_id IS NULL')->fetchColumn();
echo json_encode(['classes_checked'=>$classes,'resources'=>$resources,'definitions'=>$definitions,'abilities_with_resource_references'=>$resourceAbilities,'valid_references'=>$valid,'invalid_references'=>$invalid,'invalid_character_resource_states'=>$characterInvalid,'invalid_combat_resource_states'=>$combatInvalid],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
